\mathrm{df\text{-}real\text{-}operations}\vdash\;\begin{aligned}
x+_Ry&\coloneqq\{\langle k,q\rangle_N:k\in N\land\mathsf{Add}_Q(x(k+1),y(k+1),q)\},\\
-_Rx&\coloneqq\{\langle k,q\rangle_N:k\in N\land\mathsf{Neg}_Q(x(k),q)\},\\
x-_Ry&\coloneqq x+_R(-_Ry),\\
|x|_R&\coloneqq\{\langle k,q\rangle_N:k\in N\land\mathsf{Abs}_Q(x(k),q)\}.
\end{aligned}
